// === Tab: mySketch ===
// Attractor_14.0

let N = 3000 ; let Q = 6 ;
let M = 0.25 ; let W = 0.05 ; ; let K = 0.1 ; let H = 0.01 ; let A = 0.1 ; let S = 0.02 ; let G = 150 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let Z[] = new Array(N) ;
let KX ; let KY ; let L ; let KdX ; let KdY ; let dX ; let dY ; let dZ ;
let I ; let T ; let NX ; let NY ; let NZ ; let KN ;

function setup(){

  createCanvas(600, 600) ; noSmooth() ; background(0) ; stroke(255) ; textSize(20) ;

  X[0] = random(100,200) ; Y[0] = 0 ; ; Z[0] = 0 ;
  for ( I = 1 ; I < N ; I++ ){
    X[I] = X[0]*cos(I*2*PI/Q) + random(-0.1,+0.1) ;
    Y[I] = X[0]*sin(I*2*PI/Q) + random(-0.1,+0.1) ;
    Z[I] = Z[0] + random(-0.1,+0.1) ;
  }
  KN = N ;

}// setup()

function draw(){

  if ( KN == N ){ fill(0,0,0,20) ; rect(-1,-1,601,601) ; fill(255) ; }
  line(50,300,550,300) ; line(550,300,540,290) ; line(550,300,540,310) ; text("X",560,305) ;
  line(300,50,300,550) ; line(300,50,290,60) ; line(300,50,310,60) ; text("Z",295,40) ;
  line(450,150,150,450) ; line(150,450,150,435) ; line(150,450,165,450) ; text("Y",130,470) ;

  for ( I = 0 ; I < KN ; I++ ){

    L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
    KX = L-G ; KY = Z[I] ; T = atan(Y[I]/X[I])*2 ;
    KdY = (M*sin(W*KX)) - (K*W*KX) - (H*KY) + (A*sin(T)) ; 
    KdX = KY ;
    dX = KdX*X[I]/L + (-Y[I]*S) ; dY = KdX*Y[I]/L + (X[I]*S) ; dZ = KdY ;
    NX = X[I] + dX ; NY = Y[I] + dY ; NZ = Z[I] + dZ ;

    line(X[I]-(Y[I]/2)+300,(-Z[I]*10)+(Y[I]/2)+300,NX-(NY/2)+300,(-NZ*10)+(NY/2)+300) ;
    X[I] = NX ; Y[I] = NY ; Z[I] = NZ ;    

  }// I

}// draw()

function mousePressed(){

  background(0) ;

  if ( KN != N ){ 
    KN = N ; 
    for ( I = 1 ; I < N ; I++ ){
      X[I] = (X[0]*cos(I*2*PI/Q)) - (Y[0]*sin(I*2*PI/Q)) + random(-0.1,+0.1) ;
      Y[I] = (X[0]*sin(I*2*PI/Q)) + (Y[0]*cos(I*2*PI/Q)) + random(-0.1,+0.1) ;
      Z[I] = Z[0] + random(-0.1,+0.1) ;
    }
  }else{ KN = 1 ; }

}// mousePressed()

